SELECT s.id AS signal_id, s.symbol, s.candle_open_time, COUNT(c.open_time) AS n_closed_1m, MIN(c.open_time) AS first_open, MAX(c.open_time) AS last_open, SUM(c.number_of_trades=0) AS zero_trade_candles, SUM(c.ingestion_source<>'RUNTIME') AS non_runtime FROM crypto_ai.trade_signal s JOIN crypto_ai.candle c ON c.symbol=s.symbol AND c.interval_code='1m' AND c.closed=1 AND c.open_time BETWEEN s.candle_open_time - INTERVAL 209 MINUTE AND s.candle_open_time WHERE s.id IN (156723,159408,165412,167668,171589,176710) GROUP BY s.id, s.symbol, s.candle_open_time ORDER BY s.id;